<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { get, request, upload, download } from '../api/client'; import { workspaces, labels } from '../workspaces'
import { can } from '../permissions'
import ActivityFunctions from '../components/ActivityFunctions.vue'
const route=useRoute(),router=useRouter(),section=String(route.meta.section), config=workspaces[section] || workspaces.audit
const rows=ref<any[]>([]), detail=ref<any>(null), data=ref<any>(null), error=ref(''), busy=ref(false), dialog=ref(false), model=ref<Record<string,any>>({}), options=ref<Record<string,any[]>>({}), selected=ref<any>(null), decision=ref(''), comment=ref(''), releaseName=ref(''), releaseFile=ref(''), releaseNotes=ref(''), day=ref(new Date().toISOString().slice(0,10)), systemTab=ref('user')
const filter=ref(''),page=ref(1),filtered=computed(()=>rows.value.filter(r=>columns.value.some(c=>String(r[c]??'').toLowerCase().includes(filter.value.toLowerCase())))),pageRows=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
watch(filter,()=>page.value=1)
const userTotals=ref<any>(null)
const columns=computed(()=>section==='system'?({user:['userId','userName','nickName','deptId','status'],role:['roleId','roleName','roleKey','status'],dept:['deptId','deptName','parentId','status'],menu:['menuId','menuName','perms','status']} as Record<string,string[]>)[systemTab.value]:config.columns)
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){data.value=await get(section==='system'?`/system/${systemTab.value}/list`:config.path);rows.value=Array.isArray(data.value)?data.value:section==='analytics'?data.value.content:section==='columns'?data.value.activityColumns:data.value.rows||[];if(section==='pages')rows.value=rows.value.filter(r=>!['about','about_us'].includes(r.pageKey))}
async function initial(){await load();if(section==='analytics')userTotals.value=await get('/api/v1/admin/analytics/users');const sources=['categories','organizations','keywords','articles','subjects','files','labels'];for(const source of sources){if(config.fields?.some(f=>f.source===source)||section==='artifacts')try{options.value[source]=await get(({labels:'/api/v1/admin/catalog/labels',categories:'/api/v1/catalog/categories',organizations:'/api/v1/catalog/organizations',keywords:'/api/v1/catalog/keywords',articles:'/api/v1/admin/articles',subjects:'/api/v1/resources/subjects',files:'/api/v1/admin/files'} as Record<string,string>)[source])}catch{options.value[source]=[]}}}
function fillModel(row:any=null){selected.value=row;model.value={};for(const f of config.fields||[])model.value[f.key]=row?.[f.key]??(f.key==='name'?row?.displayName:null)??structuredClone(f.default??(f.type==='multiple'?[]:''));model.value.expectedVersion=row?.lockVersion||0;dialog.value=true}
async function open(row:any=null,hydrate=false){if(!hydrate){await router.push('/'+section+(row?'/'+row.id+'/edit':'/new'));return}await act(async()=>{if(row&&['activities','packages','review-campaigns','topics'].includes(section)){row=await get(config.path+'/'+row.id);if(section==='activities')row.fields=JSON.parse(row.form.schemaJson).fields;else if(section==='review-campaigns')row.requirements=row.requirements.map((r:any)=>({key:r.requirementKey,label:r.label,required:Boolean(r.required),mediaTypes:JSON.parse(r.fileTypeAllowlist),maxSize:r.maxSize,organizationId:JSON.parse(r.eligibilityJson).organizationId||null}));else if(section==='topics'){}else {row.type=row.resourceType;row.fileIds=[...new Set(row.files.map((f:any)=>f.fileId))]}}fillModel(row);for(const f of config.fields||[])if(f.type==='datetime'&&model.value[f.key]){const d=new Date(model.value[f.key]);model.value[f.key]=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}})}
function transformed(){const b={...model.value};for(const f of config.fields||[]){if(f.type==='datetime')b[f.key]=b[f.key]?new Date(b[f.key]).toISOString():null;else if(f.type==='number')b[f.key]=Number(b[f.key]);else if(f.source&&!b[f.key]&&f.type!=='multiple')b[f.key]=null}return b}
async function save(){await act(async()=>{let path=config.path;if(['subjects','dimensions','exams'].includes(section))path='/api/v1/admin/resources/'+section;if(section==='columns')path='/api/v1/admin/operation/activity-columns';await request(selected.value?'PUT':'POST',path+(selected.value?'/'+selected.value.id:''),transformed());dialog.value=false;await router.push('/'+section)})}
async function inspect(row:any,hydrate=false){if(!hydrate){await router.push('/'+section+'/'+row.id);return}await act(async()=>{selected.value=row;detail.value=await get(config.path+'/'+row.id);if(section==='activities')model.value.fields=JSON.parse(detail.value.form.schemaJson).fields})}
async function remove(row:any){if(!confirm('确认撤下或删除此条目？'))return;await act(async()=>{await request('DELETE',config.path+'/'+row.id+(['packages','subjects','dimensions','exams','artifacts','topics'].includes(section)?'?expectedVersion='+row.lockVersion:''));await load()})}
async function moderation(row:any,status:string){await act(async()=>{await request('POST',config.path+'/'+row.id,{status});await load()})}
async function decide(){await act(async()=>{detail.value=await request('POST',config.path+'/'+detail.value.id+'/decisions',{action:decision.value,submissionId:detail.value.currentSubmissionId,expectedVersion:detail.value.lockVersion,comment:comment.value});await load()})}
async function publishRelease(){await act(async()=>{detail.value=await request('POST',config.path+'/'+detail.value.id+'/versions',{versionName:releaseName.value,fileId:releaseFile.value,releaseNotes:releaseNotes.value});await load()})}
async function fileChanged(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file)await act(async()=>{await upload(file);await load()})}
async function keywordAlias(row:any){const alias=prompt('新增别名');if(alias)await act(async()=>{await request('POST',config.path+'/'+row.id+'/aliases',{alias});await load()})}
async function blacklist(row:any){const reason=prompt('禁用理由');if(reason)await act(async()=>{await request('POST','/api/v1/admin/catalog/blacklist',{keyword:row.displayName,reason});await load()})}
async function reconcile(row:any,outcome:string){const evidence=prompt('填写供应商回执编号、核实时间和结论（至少10字符）');if(!evidence)return;if(evidence.trim().length<10){error.value='核实证据需要至少10字符';return}await act(async()=>{await request('POST','/api/v1/admin/notifications/'+row.id+'/reconcile',{outcome,evidence});await load()})}
async function exportRows(dataset=section,activityId?:string){await act(async()=>{const result=await request('POST','/api/v1/admin/exports',{dataset,activityId});const blob=new Blob([result.csv],{type:result.contentType});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=result.filename;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);if(result.truncated)error.value=`导出已限定为 ${result.rowCount} 条，共 ${result.totalCount} 条，请分批处理。`})}
onMounted(async()=>{await act(initial);if(route.meta.mode==='new')await open(null,true);else if(route.params.id){const row=rows.value.find(r=>r.id===route.params.id);if(!row){error.value='当前列表中未找到此记录，请返回列表重新选择';return}if(route.meta.mode==='edit')await open(row,true);else await inspect(row,true)}})
</script>
<template><section><p v-if="route.meta.mode" class="error" role="alert">{{ error }}</p><button v-if="route.meta.mode" class="quiet" @click="router.push('/'+section)">返回列表</button><template v-if="!route.meta.mode"><div class="title-row"><div><h1>{{ config.title }}</h1><p class="muted">{{ config.description }}</p></div><div class="actions"><button class="quiet" :disabled="busy" @click="act(load)">刷新</button><button v-if="can('yunji:export') && ['audit','analytics'].includes(section)" class="secondary" :disabled="busy" @click="exportRows()">导出当前列表</button><button v-if="config.fields" :disabled="busy" @click="open()">新建</button></div></div><p class="error" role="alert">{{ error }}</p><div v-if="section==='files'" class="panel"><label>上传文件<input type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.zip" @change="fileChanged" /></label></div><div v-if="section==='notifications'" class="actions"><button :disabled="busy" @click="act(async()=>{await request('POST','/api/v1/admin/notifications/tick');await load()})">执行提醒任务</button></div><div v-if="section==='analytics'" class="actions"><input v-model="day" type="date" style="width:180px" /><button :disabled="busy" @click="act(async()=>{await request('POST','/api/v1/admin/analytics/aggregate',{date:day});await load()})">重新生成日报</button></div><div v-if="section==='system'" class="actions"><button v-for="tab in ['user','role','dept','menu']" :key="tab" class="secondary" @click="systemTab=tab;act(load)">{{ ({user:'用户',role:'角色',dept:'部门',menu:'菜单'} as Record<string,string>)[tab] }}</button></div>
<div class="panel actions"><input v-model="filter" placeholder="筛选已加载记录"/><span>已加载 {{ rows.length }} 条 · 筛选后 {{ filtered.length }} 条（受各接口上限限制）</span></div><div class="panel scroll" style="margin-top:20px"><table><thead><tr><th v-for="col in columns" :key="col">{{ labels[col]||col }}</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in pageRows" :key="row.id||index"><td v-for="col in columns" :key="col">{{ row[col]??'—' }}</td><td><div class="actions"><button v-if="['activities','review-applications','artifacts'].includes(section)" class="quiet" :disabled="busy" @click="inspect(row)">查看</button><button v-if="['topics','labels','categories','organizations','keywords','banners','packages','activities','review-campaigns','subjects','dimensions','exams','artifacts'].includes(section)" class="quiet" :disabled="busy" @click="open(row)">编辑</button><template v-if="['topics','categories','organizations','keywords','banners','recommendations','files','packages','subjects','dimensions','exams','artifacts'].includes(section)"><button class="danger" :disabled="busy" @click="remove(row)">撤下</button></template><button v-if="section==='files'" class="quiet" @click="act(async()=>{await download(row.id)})">下载</button><template v-if="section==='keywords'"><button class="quiet" @click="keywordAlias(row)">别名</button><button class="danger" @click="blacklist(row)">禁用</button></template><template v-if="['reports','feedback'].includes(section)&&row.status==='PENDING'"><button @click="moderation(row,'RESOLVED')">解决</button><button class="quiet" @click="moderation(row,'DISMISSED')">驳回</button></template><template v-if="section==='notifications'&&row.status==='UNKNOWN'"><button @click="reconcile(row,'SENT')">核实已送达</button><button class="danger" @click="reconcile(row,'PERMANENT_FAILURE')">核实永久失败</button></template></div></td></tr></tbody></table><div v-if="!filtered.length" class="empty">暂无匹配记录</div><div class="actions"><button class="quiet" :disabled="page===1" @click="page--">上一页</button><span>第 {{ page }} 页</span><button class="quiet" :disabled="page*20>=filtered.length" @click="page++">下一页</button></div></div>
<div v-if="section==='analytics'&&data" class="panel" style="margin-top:20px"><h2>用户汇总</h2><p class="muted">仅显示总量，不提供个人身份明细。</p><p v-if="userTotals">活跃账号 {{ userTotals.activeAccounts }} · 今日访问人数 {{ userTotals.uniqueUsersToday }} · 30日访问人数 {{ userTotals.uniqueUsers30Days }}</p><h2>每日指标</h2><table><tbody><tr v-for="(metric,i) in data.daily" :key="i"><td>{{ metric.metricDate }}</td><td>{{ metric.metricKey }}</td><td>{{ metric.value }}</td></tr></tbody></table></div>
</template><div v-if="detail" class="panel" style="margin-top:20px"><div class="title-row"><h2>{{ detail.title||detail.name||'详情' }}</h2><button class="quiet" @click="detail=null">收起</button></div><template v-if="section==='activities'"><ActivityFunctions :activity-id="detail.id" @saved="act(async()=>{detail=await get(config.path+'/'+detail.id);await load()})"/><button v-if="can('yunji:export')" class="secondary" :disabled="busy" @click="exportRows('activity-registrations',detail.id)">导出参与者名单</button><table><thead><tr><th>用户</th><th>报名状态</th><th>提交时间</th><th>答案</th></tr></thead><tbody><tr v-for="r in detail.registrations" :key="r.id"><td>{{ r.userId }}</td><td>{{ r.status }}</td><td>{{ r.submittedAt }}</td><td>{{ Object.values(JSON.parse(r.answerSnapshot)).join(' · ') }}</td></tr></tbody></table></template><template v-if="section==='review-applications'"><div v-for="f in detail.files" :key="f.submissionId+f.requirementKey" class="actions"><span>{{ f.requirementKey }} · 提交 {{ f.submissionId }}</span><button class="quiet" @click="act(async()=>{await download(f.fileId)})">查看材料</button></div><form v-if="detail.status==='SUBMITTED'" @submit.prevent="decide"><label>决定<select aria-label="决定" v-model="decision" required><option value="">选择决定</option><option>APPROVED</option><option>REJECTED</option><option>CORRECTION</option></select></label><label>意见<textarea v-model="comment" required maxlength="1000" /></label><button :disabled="busy">提交评审决定</button></form><div v-for="d in detail.decisions" :key="d.id"><p>{{ d.decision }} · {{ d.comment }}</p></div></template><template v-if="section==='artifacts'"><div v-for="v in detail.versions" :key="v.id"><h3>{{ v.versionName }}</h3><p>{{ v.releaseNotes }}</p><p class="muted">SHA256 {{ v.sha256 }}</p><button class="quiet" @click="act(async()=>{await download(v.fileId)})">下载版本</button></div><form @submit.prevent="publishRelease"><label>版本号<input v-model="releaseName" required /></label><label>发布包<select v-model="releaseFile" required><option v-for="f in options.files" :key="f.id" :value="f.id">{{ f.displayName }}</option></select></label><label>发布说明<textarea v-model="releaseNotes" required /></label><button :disabled="busy">发布版本</button></form></template></div>
<div v-if="dialog"><form class="panel module-form" @submit.prevent="save"><div class="title-row"><h2>{{ selected?'编辑':'新建' }}{{ config.title }}</h2><button type="button" class="quiet" @click="router.push('/'+section)">关闭</button></div><template v-for="f in config.fields" :key="f.key"><template v-if="f.type==='activity-fields'||f.type==='requirements'"><h3>{{ f.label }}</h3><div v-for="(field,i) in model[f.key]" :key="i" class="panel form-grid"><label>字段标识<input v-model="field.key" required /></label><label>显示名称<input v-model="field.label" required /></label><label>必填<input v-model="field.required" type="checkbox" /></label><template v-if="f.type==='activity-fields'"><label>字段类型<select v-model="field.type"><option>TEXT</option><option>NUMBER</option><option>CHOICE</option></select></label><label>最大长度<input v-model.number="field.maxLength" type="number" min="1" max="2000" /></label><label v-if="field.type==='CHOICE'">选项(逗号分隔)<input :value="field.choices.join(',')" @input="field.choices=($event.target as HTMLInputElement).value.split(',')" /></label></template><template v-else><label>文件类型<select v-model="field.mediaTypes" multiple><option>application/pdf</option><option>image/png</option><option>image/jpeg</option><option>text/plain</option></select></label><label>最大字节数<input v-model.number="field.maxSize" type="number" min="1" max="10485760" /></label></template><button type="button" class="danger" @click="model[f.key].splice(i,1)">删除字段</button></div><button type="button" class="secondary" @click="model[f.key].push(f.type==='activity-fields'?{key:'',label:'',type:'TEXT',required:true,maxLength:100,choices:[]}:{key:'',label:'',required:true,mediaTypes:['application/pdf'],maxSize:10485760,organizationId:null})">添加字段</button></template><label v-else>{{ f.label }}<select :aria-label="f.label" v-if="f.options" v-model="model[f.key]" :required="f.required"><option v-for="o in f.options" :key="o">{{ o }}</option></select><select :aria-label="f.label" v-else-if="f.source" v-model="model[f.key]" :multiple="f.type==='multiple'" :required="f.required"><option v-if="f.type!=='multiple'" value="">请选择</option><option v-for="o in options[f.source]" :key="o.id" :value="o.id">{{ o.name||o.title||o.displayName }}</option></select><textarea v-else-if="f.type==='textarea'" v-model="model[f.key]" :required="f.required" rows="10" /><input v-else-if="f.type==='boolean'" v-model="model[f.key]" type="checkbox" /><input v-else v-model="model[f.key]" :type="f.type==='datetime'?'datetime-local':f.type==='number'?'number':'text'" :required="f.required" /></label></template><div v-if="section==='topics'&&model.articleIds?.length" class="panel"><h3>专题资讯顺序</h3><div v-for="(id,i) in model.articleIds" :key="id" class="actions"><span>{{ i+1 }}. {{ options.articles?.find(a=>a.id===id)?.title||id }}</span><button type="button" class="quiet" :disabled="i===0" @click="[model.articleIds[i-1],model.articleIds[i]]=[model.articleIds[i],model.articleIds[i-1]]">上移</button><button type="button" class="quiet" :disabled="i===model.articleIds.length-1" @click="[model.articleIds[i+1],model.articleIds[i]]=[model.articleIds[i],model.articleIds[i+1]]">下移</button></div></div><p role="alert" class="error">{{ error }}</p><button :disabled="busy">保存</button></form></div></section></template>
